# --- Seed data. Codes are stable identifiers; names are display labels; list order is display order. ---

# (code, name)
DEMO_TYPES = [
    ("BOOTH", "Booth demo"),          # shown to a visitor at the stand
    ("SCHEDULED", "Scheduled demo"),  # a demo meeting booked at or after the event
    ("LIVE", "Live demo"),            # an organised demonstration for a group, e.g. a drone flight
]

# (code, name, funnel rank): higher is further along; 0 is no outcome yet or not a fit
DEMO_OUTCOMES = [
    ("PENDING", "No outcome yet", 0),
    ("NOT_A_FIT", "Not a fit", 0),
    ("FOLLOW_UP", "Follow-up booked", 1),
    ("DEMO_SCHEDULED", "Further demo scheduled", 2),
    ("DEAL_OPENED", "Deal opened", 3),
    ("CUSTOMER", "Became a customer", 4),
]


